8	import React from 'react'
9	import PropTypes from 'prop-types'
10	import {Text, VisuallyHidden} from '@salesforce/retail-react-app/app/components/shared/ui'
11	import {useIntl} from 'react-intl'
12	import msg from '@salesforce/retail-react-app/app/components/display-price/messages'
13	
14	/**
15	 * Component that displays current price of a product with a11y
16	 * @param price - price of the product
17	 * @param as - an HTML tag or component to be rendered as
18	 * @param isRange - show price as range or not
19	 * @param currency - currency to show the price in
20	 * @param labelForA11y - label to be used for a11y
21	 * @param extraProps - extra props to be passed into Text Component
22	 * @returns {JSX.Element}
23	 */
24	const CurrentPrice = ({labelForA11y, price, as, isRange = false, currency, ...extraProps}) => {
25	    const intl = useIntl()
26	    const currentPriceText = intl.formatNumber(price, {
27	        style: 'currency',
28	        currency
29	    })
30	    return (
31	        <>
32	            {isRange ? (
33	                <Text
34	                    as={as}
35	                    {...extraProps}
36	                    aria-live={'polite'}
37	                    aria-label={intl.formatMessage(msg.ariaLabelCurrentPriceWithRange, {
38	                        currentPrice: currentPriceText
39	                    })}
40	                >
41	                    {intl.formatMessage(msg.currentPriceWithRange, {
42	                        currentPrice: currentPriceText
43	                    })}
44	                </Text>
45	            ) : (
46	                <Text
47	                    as={as}
48	                    {...extraProps}
49	                    aria-label={intl.formatMessage(msg.ariaLabelCurrentPrice, {
50	                        currentPrice: currentPriceText
51	                    })}
52	                >
53	                    {currentPriceText}
54	                </Text>
55	            )}
56	            {/*For screen reader, we want to make sure the product name is announced before the price to avoid confusion*/}
57	            <VisuallyHidden aria-live="polite" aria-atomic={true}>
58	                {labelForA11y}
59	                {isRange
60	                    ? intl.formatMessage(msg.ariaLabelCurrentPriceWithRange, {
61	                          currentPrice: currentPriceText
62	                      })
63	                    : intl.formatMessage(msg.ariaLabelCurrentPrice, {
64	                          currentPrice: currentPriceText
65	                      })}
66	            </VisuallyHidden>
67	        </>
68	    )
69	}
70	CurrentPrice.propTypes = {
71	    price: PropTypes.number.isRequired,
72	    currency: PropTypes.string.isRequired,
73	    labelForA11y: PropTypes.string,
74	    as: PropTypes.string,
75	    isRange: PropTypes.bool,
76	    extraProps: PropTypes.object
